<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Desktop</title>
<style>
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body { overflow: hidden; font-family: 'Segoe UI', Ubuntu, system-ui, sans-serif; font-size: 13px; color: #eee; }

#desktop {
  width: 100vw; height: 100vh;
  background: #300A24;
  background-image:
    radial-gradient(ellipse 70% 60% at 15% 60%, rgba(120,60,160,0.35) 0%, transparent 70%),
    radial-gradient(ellipse 60% 50% at 85% 20%, rgba(40,80,200,0.25) 0%, transparent 60%),
    radial-gradient(ellipse 50% 40% at 50% 90%, rgba(180,40,80,0.15) 0%, transparent 60%);
  position: relative; overflow: hidden;
}

/* Top panel */
#top-panel {
  position: absolute; top: 0; left: 0; right: 0; height: 28px;
  background: rgba(0,0,0,0.75); backdrop-filter: blur(8px);
  display: flex; align-items: center; justify-content: flex-end;
  padding: 0 14px; gap: 16px; z-index: 2000;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  font-size: 12px; color: #ccc;
}

#clock { letter-spacing: 0.04em; }

/* Taskbar / Dock */
#taskbar {
  position: absolute; bottom: 0; left: 0; right: 0; height: 52px;
  background: rgba(10,5,20,0.88); backdrop-filter: blur(14px);
  display: flex; align-items: center; justify-content: center; gap: 10px;
  z-index: 2000; border-top: 1px solid rgba(255,255,255,0.08);
}

.taskbar-btn {
  background: rgba(255,255,255,0.08);
  color: #eee; border: 1px solid rgba(255,255,255,0.13);
  padding: 8px 20px; border-radius: 9px; cursor: pointer;
  font-size: 13px; transition: background 0.18s, border-color 0.18s;
  display: flex; align-items: center; gap: 7px;
  font-family: inherit;
}
.taskbar-btn:hover { background: rgba(233,84,32,0.45); border-color: #E95420; }
.taskbar-btn:active { background: rgba(233,84,32,0.65); }

/* Windows */
.window {
  position: absolute; display: none; flex-direction: column;
  min-width: 360px; min-height: 240px;
  background: #2b2b2b;
  border-radius: 11px;
  box-shadow: 0 28px 80px rgba(0,0,0,0.8), 0 0 0 1px rgba(255,255,255,0.1);
  overflow: hidden;
}

.win-titlebar {
  background: linear-gradient(180deg, #4a4a4a 0%, #3d3d3d 100%);
  height: 38px; display: flex; align-items: center;
  padding: 0 12px; cursor: move; user-select: none; flex-shrink: 0;
  border-bottom: 1px solid rgba(0,0,0,0.45);
}

.win-controls { display: flex; gap: 8px; margin-right: 10px; }

.win-dot {
  width: 14px; height: 14px; border-radius: 50%; border: none; cursor: pointer;
  flex-shrink: 0; transition: filter 0.15s;
}
.win-dot:hover { filter: brightness(1.3); }

.win-close { background: #ff5f57; }
.win-min-btn { background: #febc2e; }
.win-max-btn { background: #28c840; }

.win-title-text {
  flex: 1; text-align: center; color: #ccc; font-size: 13px; font-weight: 500;
  pointer-events: none;
}

/* Files app */
#files-window { width: 680px; height: 480px; }

.win-toolbar {
  background: #363636; padding: 7px 10px;
  display: flex; align-items: center; gap: 10px;
  border-bottom: 1px solid rgba(0,0,0,0.3); flex-shrink: 0;
}

#files-up {
  background: rgba(255,255,255,0.08); color: #ddd;
  border: 1px solid rgba(255,255,255,0.1); border-radius: 5px;
  padding: 4px 12px; cursor: pointer; font-size: 12px; font-family: inherit;
  transition: background 0.15s; white-space: nowrap;
}
#files-up:hover { background: rgba(255,255,255,0.16); }
#files-up:disabled { opacity: 0.4; cursor: default; }

#files-path {
  color: #bbb; font-size: 12px; font-family: 'Courier New', monospace;
  background: rgba(0,0,0,0.35); padding: 4px 12px; border-radius: 5px;
  flex: 1; border: 1px solid rgba(255,255,255,0.07);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

#files-content {
  flex: 1; overflow-y: auto; padding: 12px;
  display: flex; flex-wrap: wrap; align-content: flex-start; gap: 4px;
}

.fs-item {
  display: flex; flex-direction: column; align-items: center;
  width: 90px; padding: 9px 5px; border-radius: 7px;
  cursor: pointer; transition: background 0.14s; user-select: none;
}
.fs-item:hover { background: rgba(255,255,255,0.09); }
.fs-item.selected { background: rgba(233,84,32,0.28); }

.fs-icon { font-size: 34px; margin-bottom: 5px; line-height: 1; }

.fs-name {
  font-size: 11px; color: #ddd; text-align: center;
  word-break: break-all; max-width: 82px; line-height: 1.3;
}

/* Notepad app */
#notepad-window { width: 680px; height: 480px; }

#tabs {
  background: #2e2e2e; display: flex; align-items: stretch;
  overflow-x: auto; flex-shrink: 0;
  border-bottom: 1px solid rgba(0,0,0,0.4); min-height: 36px;
}
#tabs::-webkit-scrollbar { height: 3px; }

.tab {
  padding: 0 12px; display: flex; align-items: center; gap: 8px;
  cursor: pointer; color: #999; font-size: 12px; font-family: inherit;
  border-right: 1px solid rgba(0,0,0,0.2); white-space: nowrap;
  background: transparent; border-top: none; border-left: none; border-bottom: 2px solid transparent;
  transition: background 0.14s, color 0.14s; min-width: 90px;
}
.tab:hover { background: rgba(255,255,255,0.06); color: #ddd; }
.tab.active { background: #2b2b2b; color: #fff; border-bottom-color: #E95420; }

.tab-label { flex: 1; }

.tab-x {
  opacity: 0; font-size: 14px; line-height: 1; padding: 1px 3px;
  border-radius: 3px; cursor: pointer; color: #aaa; flex-shrink: 0;
  transition: opacity 0.14s, background 0.14s;
}
.tab:hover .tab-x, .tab.active .tab-x { opacity: 0.7; }
.tab-x:hover { opacity: 1 !important; background: rgba(255,95,87,0.25); color: #ff5f57; }

#new-tab {
  background: transparent; color: #888; border: none;
  padding: 0 14px; cursor: pointer; font-size: 20px; line-height: 36px;
  transition: color 0.14s; flex-shrink: 0;
}
#new-tab:hover { color: #E95420; }

#editor {
  flex: 1; resize: none; background: #1e1e1e; color: #d4d4d4;
  border: none; padding: 14px 16px; font-family: 'Courier New', monospace;
  font-size: 13px; line-height: 1.65; outline: none; tab-size: 4;
}

/* Scrollbars */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.18); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.28); }
</style>
</head>
<body>
<div id="desktop">

  <div id="top-panel">
    <span id="clock"></span>
  </div>

  <!-- Files Window -->
  <div id="files-window" class="window">
    <div class="win-titlebar">
      <div class="win-controls">
        <button class="win-dot win-close" title="Close"></button>
        <button class="win-dot win-min-btn" title="Minimize"></button>
        <button class="win-dot win-max-btn" title="Maximize"></button>
      </div>
      <span class="win-title-text">📁 Files</span>
    </div>
    <div class="win-toolbar">
      <button id="files-up">↑ Up</button>
      <span id="files-path">/</span>
    </div>
    <div id="files-content"></div>
  </div>

  <!-- Notepad Window -->
  <div id="notepad-window" class="window">
    <div class="win-titlebar">
      <div class="win-controls">
        <button class="win-dot win-close" title="Close"></button>
        <button class="win-dot win-min-btn" title="Minimize"></button>
        <button class="win-dot win-max-btn" title="Maximize"></button>
      </div>
      <span class="win-title-text">📝 Notepad</span>
    </div>
    <div id="tabs">
      <button id="new-tab" title="New Tab">+</button>
    </div>
    <textarea id="editor" placeholder="Start typing…"></textarea>
  </div>

  <!-- Taskbar -->
  <div id="taskbar">
    <button class="taskbar-btn" id="open-files">📁 Files</button>
    <button class="taskbar-btn" id="open-notepad">📝 Notepad</button>
  </div>

</div>
<script>
'use strict';

// ─── Clock ───────────────────────────────────────────────────
(function updateClock() {
  const el = document.getElementById('clock');
  const now = new Date();
  const d = now.toLocaleDateString(undefined, { weekday:'short', month:'short', day:'numeric' });
  const t = now.toLocaleTimeString(undefined, { hour:'2-digit', minute:'2-digit' });
  el.textContent = d + '  ' + t;
  setTimeout(updateClock, 1000);
})();

// ─── Filesystem ──────────────────────────────────────────────
const FS = {
  type: 'dir',
  children: {
    bin: { type:'dir', children:{
      bash:{type:'file'}, sh:{type:'file'}, ls:{type:'file'}, cat:{type:'file'},
      grep:{type:'file'}, mkdir:{type:'file'}, rm:{type:'file'}, cp:{type:'file'},
      mv:{type:'file'}, chmod:{type:'file'},
    }},
    etc: { type:'dir', children:{
      hostname:{type:'file'}, passwd:{type:'file'}, fstab:{type:'file'},
      hosts:{type:'file'}, timezone:{type:'file'}, os_release:{type:'file'},
      apt:{ type:'dir', children:{ 'sources.list':{type:'file'}, preferences:{type:'file'} }},
      network:{ type:'dir', children:{ interfaces:{type:'file'}, 'resolv.conf':{type:'file'} }},
      'cron.d':{ type:'dir', children:{} },
    }},
    home: { type:'dir', children:{
      user:{ type:'dir', children:{
        Documents:{ type:'dir', children:{
          'readme.txt':{type:'file'}, 'notes.md':{type:'file'}, 'todo.txt':{type:'file'},
          Projects:{ type:'dir', children:{ 'main.py':{type:'file'}, 'README.md':{type:'file'} }},
        }},
        Downloads:{ type:'dir', children:{
          'ubuntu-22.04.iso':{type:'file'}, 'setup.sh':{type:'file'},
          'archive.tar.gz':{type:'file'}, 'data.csv':{type:'file'},
        }},
        Pictures:{ type:'dir', children:{
          'wallpaper.png':{type:'file'}, 'screenshot.png':{type:'file'},
          'photo.jpg':{type:'file'},
          Vacation:{ type:'dir', children:{ 'beach.jpg':{type:'file'}, 'sunset.jpg':{type:'file'} }},
        }},
        Music:{ type:'dir', children:{
          'song.mp3':{type:'file'}, Playlist:{ type:'dir', children:{} },
        }},
        '.bashrc':{type:'file'}, '.profile':{type:'file'}, '.bash_history':{type:'file'},
        '.ssh':{ type:'dir', children:{ known_hosts:{type:'file'}, config:{type:'file'} }},
      }},
    }},
    usr: { type:'dir', children:{
      bin:{ type:'dir', children:{
        python3:{type:'file'}, node:{type:'file'}, gcc:{type:'file'},
        make:{type:'file'}, vim:{type:'file'}, curl:{type:'file'}, wget:{type:'file'},
      }},
      lib:{ type:'dir', children:{
        systemd:{ type:'dir', children:{} },
        python3:{ type:'dir', children:{ 'site-packages':{ type:'dir', children:{} } }},
      }},
      share:{ type:'dir', children:{
        doc:{ type:'dir', children:{} }, icons:{ type:'dir', children:{} },
        fonts:{ type:'dir', children:{} },
      }},
      local:{ type:'dir', children:{
        bin:{ type:'dir', children:{} }, lib:{ type:'dir', children:{} },
        share:{ type:'dir', children:{} },
      }},
    }},
    var: { type:'dir', children:{
      log:{ type:'dir', children:{
        syslog:{type:'file'}, 'auth.log':{type:'file'},
        'kern.log':{type:'file'}, 'dpkg.log':{type:'file'}, 'apt':{ type:'dir', children:{ history:{type:'file'} }},
      }},
      tmp:{ type:'dir', children:{} },
      cache:{ type:'dir', children:{ apt:{ type:'dir', children:{} } }},
      run:{ type:'dir', children:{} },
    }},
    tmp: { type:'dir', children:{} },
    proc: { type:'dir', children:{ cpuinfo:{type:'file'}, meminfo:{type:'file'}, version:{type:'file'} }},
    dev: { type:'dir', children:{
      null:{type:'file'}, zero:{type:'file'}, random:{type:'file'},
      sda:{type:'file'}, sda1:{type:'file'}, tty:{type:'file'},
    }},
    root: { type:'dir', children:{ '.bashrc':{type:'file'} }},
  }
};

function nodeAtPath(path) {
  if (!path || path === '/') return FS;
  const parts = path.replace(/^\//, '').split('/').filter(Boolean);
  let cur = FS;
  for (const p of parts) {
    if (!cur.children || !(p in cur.children)) return null;
    cur = cur.children[p];
  }
  return cur;
}

const FILE_ICONS = {
  dir: '📁',
  txt:'📄', md:'📝', sh:'⚙️', py:'🐍', js:'📜', html:'🌐',
  css:'🎨', iso:'💿', tar:'📦', gz:'📦', zip:'📦', bz2:'📦',
  png:'🖼️', jpg:'🖼️', jpeg:'🖼️', gif:'🖼️', svg:'🖼️',
  log:'📋', conf:'⚙️', list:'📋', csv:'📊', json:'📊',
  mp3:'🎵', mp4:'🎬', pdf:'📕', c:'🔧', h:'🔧',
};

function fileIcon(name, type) {
  if (type === 'dir') return FILE_ICONS.dir;
  const ext = name.includes('.') ? name.split('.').pop().toLowerCase() : '';
  return FILE_ICONS[ext] || '📄';
}

// Files state
let currentPath = '/';

function renderFiles() {
  const pathEl = document.getElementById('files-path');
  const content = document.getElementById('files-content');
  const upBtn = document.getElementById('files-up');

  pathEl.textContent = currentPath || '/';
  upBtn.disabled = (currentPath === '/');

  content.innerHTML = '';
  const node = nodeAtPath(currentPath);
  if (!node || node.type !== 'dir') return;

  const entries = Object.entries(node.children || {});
  entries.sort(([an, av], [bn, bv]) => {
    if (av.type !== bv.type) return av.type === 'dir' ? -1 : 1;
    return an.localeCompare(bn);
  });

  for (const [name, child] of entries) {
    const item = document.createElement('div');
    item.className = 'fs-item';
    item.dataset.name = name;

    const icon = document.createElement('div');
    icon.className = 'fs-icon';
    icon.textContent = fileIcon(name, child.type);

    const label = document.createElement('div');
    label.className = 'fs-name';
    label.textContent = name;

    item.appendChild(icon);
    item.appendChild(label);

    item.addEventListener('click', () => {
      content.querySelectorAll('.fs-item').forEach(i => i.classList.remove('selected'));
      item.classList.add('selected');
    });

    if (child.type === 'dir') {
      item.addEventListener('dblclick', () => {
        currentPath = currentPath === '/' ? '/' + name : currentPath + '/' + name;
        renderFiles();
      });
    }

    content.appendChild(item);
  }
}

document.getElementById('files-up').addEventListener('click', () => {
  if (currentPath === '/') return;
  const parts = currentPath.replace(/^\//, '').split('/').filter(Boolean);
  parts.pop();
  currentPath = parts.length ? '/' + parts.join('/') : '/';
  renderFiles();
});

// ─── Notepad / localStorage ───────────────────────────────────
const STORE_TABS = 'notepad_tabs_v2';
const STORE_ACTIVE = 'notepad_active_v2';

let tabs = [];
let activeId = null;
let _tabSeq = 0;

function newId() { return 't' + (++_tabSeq); }

function saveTabs() {
  try {
    localStorage.setItem(STORE_TABS, JSON.stringify(tabs));
    localStorage.setItem(STORE_ACTIVE, activeId || '');
  } catch(e) {}
}

function loadTabs() {
  try {
    const raw = localStorage.getItem(STORE_TABS);
    if (raw) {
      tabs = JSON.parse(raw);
      const maxSeq = tabs.reduce((m, t) => Math.max(m, parseInt(t.id.slice(1)) || 0), 0);
      _tabSeq = maxSeq;
    }
    const saved = localStorage.getItem(STORE_ACTIVE);
    if (saved && tabs.some(t => t.id === saved)) activeId = saved;
    else if (tabs.length) activeId = tabs[0].id;
  } catch(e) { tabs = []; }

  if (!tabs.length) addTab('Untitled 1', '');
}

function addTab(name, content) {
  const id = newId();
  tabs.push({ id, name, content: content || '' });
  activeId = id;
  saveTabs();
  renderTabStrip();
  syncEditor();
}

function removeTab(id) {
  const idx = tabs.findIndex(t => t.id === id);
  if (idx === -1) return;
  tabs.splice(idx, 1);
  if (!tabs.length) { addTab('Untitled 1', ''); return; }
  if (activeId === id) activeId = tabs[Math.min(idx, tabs.length - 1)].id;
  saveTabs();
  renderTabStrip();
  syncEditor();
}

function switchTab(id) {
  // Save current content first
  flushEditor();
  activeId = id;
  saveTabs();
  renderTabStrip();
  syncEditor();
}

function flushEditor() {
  const tab = tabs.find(t => t.id === activeId);
  if (tab) tab.content = document.getElementById('editor').value;
}

function syncEditor() {
  const tab = tabs.find(t => t.id === activeId);
  document.getElementById('editor').value = tab ? tab.content : '';
}

function renderTabStrip() {
  const strip = document.getElementById('tabs');
  strip.querySelectorAll('.tab').forEach(el => el.remove());
  const newBtn = document.getElementById('new-tab');

  for (const tab of tabs) {
    const el = document.createElement('button');
    el.className = 'tab' + (tab.id === activeId ? ' active' : '');
    el.dataset.id = tab.id;

    const label = document.createElement('span');
    label.className = 'tab-label';
    label.textContent = tab.name;

    const x = document.createElement('span');
    x.className = 'tab-x';
    x.textContent = '×';
    x.addEventListener('click', e => { e.stopPropagation(); removeTab(tab.id); });

    el.appendChild(label);
    el.appendChild(x);
    el.addEventListener('click', () => switchTab(tab.id));

    strip.insertBefore(el, newBtn);
  }
}

document.getElementById('new-tab').addEventListener('click', () => {
  const untitled = tabs.filter(t => t.name.startsWith('Untitled')).length;
  addTab('Untitled ' + (untitled + 1), '');
});

document.getElementById('editor').addEventListener('input', e => {
  const tab = tabs.find(t => t.id === activeId);
  if (tab) { tab.content = e.target.value; saveTabs(); }
});

// ─── Window management ────────────────────────────────────────
let _z = 200;
function bringFront(win) { win.style.zIndex = ++_z; }

function showWindow(win) {
  if (win.style.display === 'flex') { bringFront(win); return; }
  // Center on first open or if off screen
  const W = win.offsetWidth || parseInt(win.style.width) || 680;
  const H = win.offsetHeight || parseInt(win.style.height) || 480;
  const vw = document.documentElement.clientWidth;
  const vh = document.documentElement.clientHeight;
  const l = Math.max(10, (vw - W) / 2);
  const t = Math.max(36, (vh - H - 52) / 2 + 28);
  win.style.left = l + 'px';
  win.style.top  = t + 'px';
  win.style.display = 'flex';
  bringFront(win);
}

function hideWindow(win) { win.style.display = 'none'; }

// Wire close buttons
document.querySelectorAll('.win-close').forEach(btn => {
  btn.addEventListener('click', () => hideWindow(btn.closest('.window')));
});

// Wire launchers
document.getElementById('open-files').addEventListener('click', () => {
  const win = document.getElementById('files-window');
  showWindow(win);
  renderFiles();
});

document.getElementById('open-notepad').addEventListener('click', () => {
  const win = document.getElementById('notepad-window');
  showWindow(win);
  renderTabStrip();
  syncEditor();
});

// Bring to front on click
document.querySelectorAll('.window').forEach(win => {
  win.addEventListener('mousedown', () => bringFront(win), true);
});

// ─── Drag ─────────────────────────────────────────────────────
document.querySelectorAll('.win-titlebar').forEach(bar => {
  const win = bar.closest('.window');
  let dragging = false, ox, oy, sl, st;

  bar.addEventListener('mousedown', e => {
    if (e.target.closest('.win-dot')) return;
    dragging = true;
    ox = e.clientX; oy = e.clientY;
    sl = win.offsetLeft; st = win.offsetTop;
    bringFront(win);
    e.preventDefault();
  });

  document.addEventListener('mousemove', e => {
    if (!dragging) return;
    const nx = Math.max(0, sl + e.clientX - ox);
    const ny = Math.max(28, st + e.clientY - oy);
    win.style.left = nx + 'px';
    win.style.top  = ny + 'px';
  });

  document.addEventListener('mouseup', () => { dragging = false; });
});

// ─── Resize windows (edge drag) ───────────────────────────────
// Simple SE corner resize
(function addResize() {
  document.querySelectorAll('.window').forEach(win => {
    const handle = document.createElement('div');
    handle.style.cssText =
      'position:absolute;right:0;bottom:0;width:14px;height:14px;cursor:se-resize;z-index:10;';
    win.appendChild(handle);

    let resizing = false, ox, oy, ow, oh;
    handle.addEventListener('mousedown', e => {
      resizing = true;
      ox = e.clientX; oy = e.clientY;
      ow = win.offsetWidth; oh = win.offsetHeight;
      e.stopPropagation(); e.preventDefault();
    });
    document.addEventListener('mousemove', e => {
      if (!resizing) return;
      const nw = Math.max(360, ow + e.clientX - ox);
      const nh = Math.max(240, oh + e.clientY - oy);
      win.style.width  = nw + 'px';
      win.style.height = nh + 'px';
    });
    document.addEventListener('mouseup', () => { resizing = false; });
  });
})();

// ─── Init ─────────────────────────────────────────────────────
loadTabs();
</script>
</body>
</html>
